def clean(df):
    df = df.copy()
    df['Category'] = df['Category'].str.strip()
    df['Region'] = df['Region'].replace({'Suoth': 'South', 'Nort': 'North'})
    return df.dropna(subset=['Region'])

def answer(df):
    electronics = df[df['Category'] == 'Electronics']
    grouped = electronics.groupby('Region')['Revenue'].sum().reset_index()
    return {row['Region']: row['Revenue'] for _, row in grouped.iterrows()}
